    const ruleBtn = r => { const on = !!U.v[r.k]; return `<button type="button" class="lc2-rule ${on ? 'on' : ''} ${r.risk ? 'risk' : ''}" data-rule="${r.k}" aria-pressed="${on}"><i></i><span>${r.g ? `<code>${r.g}</code> ` : ''}${r.t}<small>${r.sub}</small></span></button>`; };
