          if (c.act === 'update') { chg++; ln('c', '  # aws_db_instance.orders will be updated in-place'); ln('chg', '  ~ resource "aws_db_instance" "orders" {'); ln('chg', '      ~ instance_class = ' + cls); ln('', '        # (24 unchanged attributes hidden)'); }
