      const drift = C.drift ? `<div class="lc2-card warn"><b>Дрейф.</b><p>Ручная правка в консоли: Terraform её не знает, поэтому план покажет «~» и вернёт как в коде — дыра закроется. Если ручная правка была нужна (ночной хотфикс), её переносят в код, иначе её молча откатит первый же apply. Дрейф ищут заранее: <code>terraform plan -refresh-only</code> по расписанию.</p></div>` : '';
